// ── SLIDESHOW COMPONENT ───────────────────────────────────────────────────────
function SlideShow({ slides }) {
  const [current, setCurrent] = useState(0);
  const [animating, setAnimating] = useState(false);
  const [direction, setDirection] = useState("next");

  function goTo(idx, dir) {
    if (animating || idx === current) return;
    setDirection(dir);
    setAnimating(true);
    setTimeout(() => {
      setCurrent(idx);
      setAnimating(false);
    }, 300);
  }

  function next() { goTo((current + 1) % slides.length, "next"); }
  function prev() { goTo((current - 1 + slides.length) % slides.length, "prev"); }

  const slide = slides[current];

  return (
    <div style={{ userSelect:"none" }}>
      {/* Slide */}
      <div style={{
        background: `linear-gradient(135deg, ${slide.color}18, ${slide.color}08)`,
        border: `1px solid ${slide.color}44`,
        borderRadius: 14,
        padding: "48px 40px",
        textAlign: "center",
        minHeight: 280,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        opacity: animating ? 0 : 1,
        transform: animating ? (direction === "next" ? "translateX(30px)" : "translateX(-30px)") : "translateX(0)",
        transition: "opacity .3s ease, transform .3s ease",
        position: "relative",
        overflow: "hidden",
      }}>
        {/* Background number */}
        <div style={{ position:"absolute", bottom:-20, right:10, fontFamily:"'Bebas Neue',sans-serif", fontSize:120, color:`${slide.color}10`, lineHeight:1, pointerEvents:"none" }}>
          {current + 1}
        </div>
        <div style={{ fontSize: 56, marginBottom: 16 }}>{slide.icon}</div>
        <div style={{ fontFamily:"'Bebas Neue',sans-serif", fontSize: 28, letterSpacing: 1.5, color: slide.color, marginBottom: 16 }}>
          {slide.title}
        </div>
        <div style={{ fontSize: 15, lineHeight: 1.8, color: "var(--text)", maxWidth: 500 }}>
          {slide.body}
        </div>
      </div>

      {/* Controls */}
      <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginTop:20 }}>
        <button onClick={prev}
          style={{ background:"var(--surface2)", border:"1px solid var(--border)", borderRadius:8, color:"var(--text)", padding:"10px 20px", cursor:"pointer", fontFamily:"Barlow,sans-serif", fontSize:14 }}>
          ← Prev
        </button>

        {/* Dots */}
        <div style={{ display:"flex", gap:8 }}>
          {slides.map((s, i) => (
            <div key={i} onClick={() => goTo(i, i > current ? "next" : "prev")}
              style={{ width: i === current ? 24 : 8, height:8, borderRadius:99, cursor:"pointer",
                background: i === current ? slide.color : "var(--border)",
                transition:"all .3s ease" }} />
          ))}
        </div>

        <button onClick={next}
          style={{ background:"var(--surface2)", border:"1px solid var(--border)", borderRadius:8, color:"var(--text)", padding:"10px 20px", cursor:"pointer", fontFamily:"Barlow,sans-serif", fontSize:14 }}>
          Next →
        </button>
      </div>

      {/* Slide counter */}
      <div style={{ textAlign:"center", marginTop:12, fontSize:12, color:"var(--muted)" }}>
        {current + 1} of {slides.length}
      </div>
    </div>
  );
}

// ── MODULE VIEWER ─────────────────────────────────────────────────────────────
function ModuleViewer({ user, moduleId, onBack, onComplete }) {
  const [lessonIdx, setLessonIdx] = useState(0);
  const [showQuiz, setShowQuiz]   = useState(false);
  const [answers, setAnswers]     = useState({});
  const [submitted, setSubmitted] = useState(false);
  const [score, setScore]         = useState(0);

  const mod     = SEED_MODULES.find(m => m.id === moduleId);
  const content = MODULE_CONTENT[moduleId];
  const lessons = content.lessons;
  const lesson  = lessons[lessonIdx];
  const progress= Math.round(((lessonIdx + 1) / lessons.length) * 100);

  function handleAnswer(qi, ai) {
    if (submitted) return;
    setAnswers(prev => ({ ...prev, [qi]: ai }));
  }

  function handleSubmit() {
    let correct = 0;
    content.quiz.forEach((q, i) => { if (answers[i] === q.answer) correct++; });
    const pct = Math.round((correct / content.quiz.length) * 100);
    setScore(pct);
    setSubmitted(true);
    if (pct >= 70) onComplete(moduleId, 100);
  }

  const allAnswered = content.quiz.every((_, i) => answers[i] !== undefined);
  const passed = submitted && score >= 70;

  return (
    <div>
      {/* Header */}
      <div style={{ display:"flex", alignItems:"center", gap:14, marginBottom:24 }}>
        <button onClick={onBack} style={{ background:"none", border:"1px solid var(--border)", borderRadius:8, color:"var(--muted)", padding:"8px 14px", cursor:"pointer", fontFamily:"Barlow,sans-serif", fontSize:13 }}>← Back</button>
        <div>
          <div style={{ fontFamily:"'Bebas Neue',sans-serif", fontSize:28, letterSpacing:1 }}>{mod.title}</div>
          <div style={{ fontSize:12, color:"var(--muted)", marginTop:2 }}>{mod.category} · {mod.duration} · {lessons.length} lessons</div>
        </div>
      </div>

      <div style={{ display:"grid", gridTemplateColumns:"260px 1fr", gap:20 }}>
        {/* Lesson list sidebar */}
        <div style={{ background:"var(--surface)", border:"1px solid var(--border)", borderRadius:10, padding:16, height:"fit-content" }}>
          <div style={{ fontSize:11, fontWeight:700, letterSpacing:2, textTransform:"uppercase", color:"var(--muted)", marginBottom:12 }}>Lessons</div>
          {lessons.map((l, i) => (
            <div key={l.id} onClick={() => { setShowQuiz(false); setLessonIdx(i); }}
              style={{ display:"flex", alignItems:"center", gap:10, padding:"10px 12px", borderRadius:8, cursor:"pointer", marginBottom:4,
                background: lessonIdx===i && !showQuiz ? "rgba(201,168,76,.12)" : "transparent",
                color: lessonIdx===i && !showQuiz ? "var(--gold)" : "var(--text)" }}>
              <div style={{ width:22, height:22, borderRadius:"50%", background: i < lessonIdx ? "var(--success)" : lessonIdx===i && !showQuiz ? "var(--gold)" : "var(--surface2)",
                display:"flex", alignItems:"center", justifyContent:"center", fontSize:10, fontWeight:700, color: i<=lessonIdx?"#111":"var(--muted)", flexShrink:0 }}>
                {i < lessonIdx ? "✓" : i+1}
              </div>
              <span style={{ fontSize:13, lineHeight:1.3 }}>{l.title}</span>
            </div>
          ))}
          <div onClick={() => setShowQuiz(true)}
            style={{ display:"flex", alignItems:"center", gap:10, padding:"10px 12px", borderRadius:8, cursor:"pointer", marginTop:8,
              background: showQuiz ? "rgba(201,168,76,.12)" : "transparent",
              color: showQuiz ? "var(--gold)" : "var(--muted)",
              borderTop:"1px solid var(--border)", paddingTop:14 }}>
            <div style={{ width:22, height:22, borderRadius:"50%", background: submitted && passed ? "var(--success)" : showQuiz ? "var(--gold)" : "var(--surface2)",
              display:"flex", alignItems:"center", justifyContent:"center", fontSize:10, color:"#111", flexShrink:0 }}>
              {submitted && passed ? "✓" : "?"}
            </div>
            <span style={{ fontSize:13 }}>Module Quiz</span>
          </div>
        </div>

        {/* Main content area */}
        <div>
          {!showQuiz ? (
            <div>
              {/* Lesson progress bar */}
              <div style={{ background:"var(--surface)", border:"1px solid var(--border)", borderRadius:10, padding:20, marginBottom:16 }}>
                <div style={{ display:"flex", justifyContent:"space-between", marginBottom:8 }}>
                  <span style={{ fontSize:12, color:"var(--muted)" }}>Lesson {lessonIdx+1} of {lessons.length}</span>
                  <span style={{ fontSize:12, fontWeight:600, color:"var(--gold)" }}>{progress}%</span>
                </div>
                <div style={{ height:6, background:"var(--surface2)", borderRadius:99, overflow:"hidden" }}>
                  <div style={{ height:"100%", width:`${progress}%`, background:"linear-gradient(90deg,var(--gold),#f0c040)", borderRadius:99, transition:"width .4s" }} />
                </div>
              </div>

              {/* Lesson content */}
              <div style={{ background:"var(--surface)", border:"1px solid var(--border)", borderRadius:10, padding:28, marginBottom:16 }}>
                <div style={{ fontFamily:"'Bebas Neue',sans-serif", fontSize:22, letterSpacing:1, marginBottom:16, color:"var(--gold)" }}>{lesson.title}</div>
                {lesson.type === "slides" ? (
                  <SlideShow slides={lesson.slides} />
                ) : lesson.type === "team" ? (
                  <div style={{ display:"flex", flexDirection:"column", gap:20 }}>
                    {lesson.team.map((member, i) => (
                      <div key={i} style={{ display:"flex", alignItems:"flex-start", gap:20, background:"var(--surface2)", borderRadius:10, padding:20, border:"1px solid var(--border)" }}>
                        <div style={{ width:80, height:80, borderRadius:10, background:"var(--surface)", border:"2px dashed var(--gold)", display:"flex", flexDirection:"column", alignItems:"center", justifyContent:"center", flexShrink:0, gap:4 }}>
                          <div style={{ fontSize:24 }}>📷</div>
                          <div style={{ fontSize:9, color:"var(--muted)", textAlign:"center", letterSpacing:1 }}>PHOTO<br/>NEEDED</div>
                        </div>
                        <div style={{ flex:1 }}>
                          <div style={{ fontFamily:"'Bebas Neue',sans-serif", fontSize:20, letterSpacing:1, color:"var(--text)" }}>{member.name}</div>
                          <div style={{ fontSize:12, color:"var(--gold)", fontWeight:700, letterSpacing:1, textTransform:"uppercase", marginBottom:8 }}>{member.title}</div>
                          <div style={{ fontSize:14, color:"var(--muted)", lineHeight:1.7 }}>{member.bio}</div>
                        </div>
                      </div>
                    ))}
                  </div>
                ) : lesson.type === "video" ? (
                  lesson.videoId === "placeholder" ? (
                    <div style={{ background:"var(--surface2)", border:"2px dashed var(--gold)", borderRadius:8, padding:"40px 20px", textAlign:"center" }}>
                      <div style={{ fontSize:40, marginBottom:12 }}>🎬</div>
                      <div style={{ fontFamily:"'Bebas Neue',sans-serif", fontSize:20, color:"var(--gold)", marginBottom:6 }}>Video Coming Soon</div>
                      <div style={{ fontSize:13, color:"var(--muted)" }}>This video is on the <strong style={{color:"var(--gold)"}}>Content Needed</strong> list and will be added once recorded.</div>
                    </div>
                  ) : (
                  <div style={{ position:"relative", paddingBottom:"56.25%", height:0, borderRadius:8, overflow:"hidden" }}>
                    <iframe src={lesson.videoId} style={{ position:"absolute", top:0, left:0, width:"100%", height:"100%", border:"none" }} allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowFullScreen title={lesson.title} referrerPolicy="strict-origin-when-cross-origin" />
                  </div>
                  )
                ) : (
                  <p style={{ fontSize:15, lineHeight:1.8, color:"var(--text)" }}>{lesson.content}</p>
                )}
              </div>

              {/* Navigation */}
              <div style={{ display:"flex", justifyContent:"space-between" }}>
                <button onClick={() => setLessonIdx(i => Math.max(0, i-1))} disabled={lessonIdx===0}
                  style={{ padding:"10px 22px", borderRadius:8, border:"1px solid var(--border)", background:"var(--surface2)", color: lessonIdx===0 ? "var(--muted)" : "var(--text)", cursor: lessonIdx===0?"not-allowed":"pointer", fontFamily:"Barlow,sans-serif", fontSize:14 }}>
                  ← Previous
                </button>
                {lessonIdx < lessons.length - 1 ? (
                  <button onClick={() => setLessonIdx(i => i+1)}
                    style={{ padding:"10px 22px", borderRadius:8, border:"none", background:"var(--gold)", color:"#111", cursor:"pointer", fontFamily:"'Bebas Neue',sans-serif", fontSize:16, letterSpacing:1 }}>
                    Next Lesson →
                  </button>
                ) : (
                  <button onClick={() => setShowQuiz(true)}
                    style={{ padding:"10px 22px", borderRadius:8, border:"none", background:"var(--gold)", color:"#111", cursor:"pointer", fontFamily:"'Bebas Neue',sans-serif", fontSize:16, letterSpacing:1 }}>
                    Take Quiz →
                  </button>
                )}
              </div>
            </div>
          ) : (
            /* Quiz */
            <div style={{ background:"var(--surface)", border:"1px solid var(--border)", borderRadius:10, padding:28 }}>
              <div style={{ fontFamily:"'Bebas Neue',sans-serif", fontSize:26, letterSpacing:1, marginBottom:6 }}>Module Quiz</div>
              <div style={{ fontSize:13, color:"var(--muted)", marginBottom:24 }}>Answer all questions. You need 70% to pass.</div>

              {submitted && (
                <div style={{ padding:"16px 20px", borderRadius:10, marginBottom:24, textAlign:"center",
                  background: passed ? "rgba(91,140,90,.15)" : "rgba(192,87,58,.15)",
                  border: `1px solid ${passed ? "var(--success)" : "var(--danger)"}` }}>
                  <div style={{ fontFamily:"'Bebas Neue',sans-serif", fontSize:32, color: passed ? "var(--success)" : "var(--danger)" }}>
                    {score}% — {passed ? "🎉 Passed!" : "❌ Try Again"}
                  </div>
                  <div style={{ fontSize:13, color:"var(--muted)", marginTop:4 }}>
                    {passed ? "Module complete! Great work." : "Review the lessons and try again. You need 70% to pass."}
                  </div>
                </div>
              )}

              {content.quiz.map((q, qi) => (
                <div key={qi} style={{ marginBottom:24 }}>
                  <div style={{ fontSize:15, fontWeight:600, marginBottom:12 }}>{qi+1}. {q.q}</div>
                  <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
                    {q.options.map((opt, ai) => {
                      let bg = "var(--surface2)", border = "var(--border)", color = "var(--text)";
                      if (answers[qi] === ai) { bg = "rgba(201,168,76,.15)"; border = "var(--gold)"; color = "var(--gold)"; }
                      if (submitted) {
                        if (ai === q.answer) { bg = "rgba(91,140,90,.2)"; border = "var(--success)"; color = "var(--success)"; }
                        else if (answers[qi] === ai) { bg = "rgba(192,87,58,.15)"; border = "var(--danger)"; color = "var(--danger)"; }
                      }
                      return (
                        <div key={ai} onClick={() => handleAnswer(qi, ai)}
                          style={{ padding:"12px 16px", borderRadius:8, border:`1px solid ${border}`, background:bg, color, cursor: submitted?"default":"pointer", fontSize:14, transition:"all .15s" }}>
                          {opt}
                        </div>
                      );
                    })}
                  </div>
                </div>
              ))}

              {!submitted ? (
                <button onClick={handleSubmit} disabled={!allAnswered}
                  style={{ width:"100%", padding:"14px", borderRadius:10, border:"none", background: allAnswered ? "var(--gold)" : "var(--surface2)",
                    color: allAnswered ? "#111" : "var(--muted)", cursor: allAnswered ? "pointer" : "not-allowed",
                    fontFamily:"'Bebas Neue',sans-serif", fontSize:18, letterSpacing:2 }}>
                  Submit Quiz
                </button>
              ) : !passed ? (
                <button onClick={() => { setAnswers({}); setSubmitted(false); }}
                  style={{ width:"100%", padding:"14px", borderRadius:10, border:"none", background:"var(--gold)", color:"#111", cursor:"pointer", fontFamily:"'Bebas Neue',sans-serif", fontSize:18, letterSpacing:2 }}>
                  Retry Quiz
                </button>
              ) : (
                <button onClick={onBack}
                  style={{ width:"100%", padding:"14px", borderRadius:10, border:"none", background:"var(--success)", color:"#fff", cursor:"pointer", fontFamily:"'Bebas Neue',sans-serif", fontSize:18, letterSpacing:2 }}>
                  ✓ Back to Modules
                </button>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}


// ── ADMIN MODULE EDITOR ───────────────────────────────────────────────────────
function AdminModules({ onToast }) {
  const [modules, setModules]     = useState(JSON.parse(JSON.stringify(SEED_MODULES)));
  const [editing, setEditing]     = useState(null);   // module being edited
  const [creating, setCreating]   = useState(false);
  const [quizEdit, setQuizEdit]   = useState(null);   // moduleId for quiz editor
  const [content, setContent]     = useState(JSON.parse(JSON.stringify(MODULE_CONTENT)));

  const blank = { id: Date.now(), title:"", category:"Safety", description:"", duration:"30 min", lessons:1, color:"#C9A84C" };

  function saveModule(mod) {
    setModules(prev => {
      const exists = prev.find(m => m.id === mod.id);
      if (exists) return prev.map(m => m.id === mod.id ? mod : m);
      return [...prev, mod];
    });
    if (!content[mod.id]) {
      setContent(prev => ({ ...prev, [mod.id]: { video:"", lessons:[], quiz:[] } }));
    }
    setEditing(null);
    setCreating(false);
    onToast("✅ Module saved!");
  }

  function deleteModule(id) {
    setModules(prev => prev.filter(m => m.id !== id));
    onToast("🗑 Module deleted.");
  }

  if (quizEdit) {
    return <QuizEditor moduleId={quizEdit} content={content} setContent={setContent}
      onBack={() => setQuizEdit(null)} onToast={onToast} modules={modules} />;
  }

  if (editing || creating) {
    const mod = creating ? blank : editing;
    return <ModuleForm mod={mod} onSave={saveModule} onCancel={() => { setEditing(null); setCreating(false); }} />;
  }

  return (
    <div>
      <div className="page-header">
        <h1>Manage Modules</h1>
        <p>Add, edit, or remove training modules and quizzes.</p>
      </div>
      <div style={{ display:"flex", justifyContent:"flex-end", marginBottom:16 }}>
        <button className="btn-add" onClick={() => setCreating(true)}>+ Add Module</button>
      </div>
      <div className="table-wrap">
        {modules.map(m => (
          <div className="admin-module-row" key={m.id}>
            <div className="am-dot" style={{ background: m.color }} />
            <div className="am-info">
              <div className="am-title">{m.title}</div>
              <div className="am-meta">{m.category} · {m.duration}</div>
            </div>
            <button className="btn-sm" onClick={() => setQuizEdit(m.id)}>Edit Quiz</button>
            <button className="btn-sm" onClick={() => setEditing(m)}>Edit</button>
            <button className="btn-sm" style={{ color:"var(--danger)" }} onClick={() => deleteModule(m.id)}>Delete</button>
          </div>
        ))}
      </div>
    </div>
  );
}

// ── MODULE FORM ───────────────────────────────────────────────────────────────
function ModuleForm({ mod, onSave, onCancel }) {
  const [form, setForm] = useState({ ...mod });
  const categories = ["Safety","Installation","Sales","Inspection","Products","Other"];
  const colors = ["#C9A84C","#4A7FA5","#5B8C5A","#8B5E83","#C0573A","#E8A020"];

  function set(k, v) { setForm(prev => ({ ...prev, [k]: v })); }

  return (
    <div>
      <div className="page-header">
        <h1>{mod.title ? "Edit Module" : "New Module"}</h1>
      </div>
      <div style={{ background:"var(--surface)", border:"1px solid var(--border)", borderRadius:10, padding:28, maxWidth:600 }}>
        {[["Module Title","title","text"],["Description","description","textarea"],["Duration","duration","text"]].map(([label,key,type]) => (
          <div className="field-wrap" key={key}>
            <label className="field-label">{label}</label>
            {type === "textarea"
              ? <textarea className="field-input" rows={3} style={{ resize:"vertical" }} value={form[key]||""} onChange={e=>set(key,e.target.value)} />
              : <input className="field-input" value={form[key]||""} onChange={e=>set(key,e.target.value)} />}
          </div>
        ))}
        <div className="field-wrap">
          <label className="field-label">Category</label>
          <select className="field-input" value={form.category} onChange={e=>set("category",e.target.value)}>
            {categories.map(c => <option key={c}>{c}</option>)}
          </select>
        </div>
        <div className="field-wrap">
          <label className="field-label">Color</label>
          <div style={{ display:"flex", gap:10, marginTop:4 }}>
            {colors.map(c => (
              <div key={c} onClick={() => set("color",c)}
                style={{ width:32, height:32, borderRadius:"50%", background:c, cursor:"pointer",
                  border: form.color===c ? "3px solid white" : "3px solid transparent" }} />
            ))}
          </div>
        </div>
        <div style={{ display:"flex", gap:10, marginTop:8 }}>
          <button className="btn-add" onClick={() => onSave(form)} style={{ flex:1, justifyContent:"center" }}>Save Module</button>
          <button className="btn-sm" onClick={onCancel} style={{ padding:"10px 20px" }}>Cancel</button>
        </div>
      </div>
    </div>
  );
}

// ── QUIZ EDITOR ───────────────────────────────────────────────────────────────
function QuizEditor({ moduleId, content, setContent, onBack, onToast, modules }) {
  const mod = modules.find(m => m.id === moduleId);
  const quiz = content[moduleId]?.quiz || [];
  const [questions, setQuestions] = useState(JSON.parse(JSON.stringify(quiz)));

  const blankQ = { q:"", options:["","","",""], answer:0 };

  function addQuestion() { setQuestions(prev => [...prev, { ...blankQ, options:["","","",""] }]); }
  function removeQ(i) { setQuestions(prev => prev.filter((_,idx) => idx !== i)); }
  function setQ(i, key, val) {
    setQuestions(prev => prev.map((q,idx) => idx===i ? { ...q, [key]: val } : q));
  }
  function setOpt(qi, oi, val) {
    setQuestions(prev => prev.map((q,idx) => idx===qi
      ? { ...q, options: q.options.map((o,j) => j===oi ? val : o) } : q));
  }

  function save() {
    setContent(prev => ({ ...prev, [moduleId]: { ...prev[moduleId], quiz: questions } }));
    onToast("✅ Quiz saved!");
    onBack();
  }

  return (
    <div>
      <div style={{ display:"flex", alignItems:"center", gap:14, marginBottom:24 }}>
        <button onClick={onBack} style={{ background:"none", border:"1px solid var(--border)", borderRadius:8, color:"var(--muted)", padding:"8px 14px", cursor:"pointer", fontFamily:"Barlow,sans-serif", fontSize:13 }}>← Back</button>
        <div className="page-header" style={{ margin:0 }}>
          <h1>Quiz Editor — {mod?.title}</h1>
          <p>Build quiz questions. Mark the correct answer.</p>
        </div>
      </div>

      {questions.map((q, qi) => (
        <div key={qi} style={{ background:"var(--surface)", border:"1px solid var(--border)", borderRadius:10, padding:24, marginBottom:16 }}>
          <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:14 }}>
            <div style={{ fontFamily:"'Bebas Neue',sans-serif", fontSize:18, color:"var(--gold)" }}>Question {qi+1}</div>
            <button className="btn-sm" style={{ color:"var(--danger)" }} onClick={() => removeQ(qi)}>Remove</button>
          </div>
          <div className="field-wrap">
            <label className="field-label">Question Text</label>
            <input className="field-input" value={q.q} onChange={e => setQ(qi,"q",e.target.value)} placeholder="Enter your question..." />
          </div>
          <label className="field-label" style={{ marginBottom:8, display:"block" }}>Answer Options — click to mark correct</label>
          {q.options.map((opt, oi) => (
            <div key={oi} style={{ display:"flex", gap:10, alignItems:"center", marginBottom:8 }}>
              <div onClick={() => setQ(qi,"answer",oi)}
                style={{ width:24, height:24, borderRadius:"50%", flexShrink:0, cursor:"pointer",
                  background: q.answer===oi ? "var(--success)" : "var(--surface2)",
                  border: `2px solid ${q.answer===oi ? "var(--success)" : "var(--border)"}`,
                  display:"flex", alignItems:"center", justifyContent:"center", fontSize:11, color:"#fff" }}>
                {q.answer===oi ? "✓" : ""}
              </div>
              <input className="field-input" value={opt} onChange={e => setOpt(qi,oi,e.target.value)}
                placeholder={`Option ${oi+1}`} style={{ flex:1,
                  borderColor: q.answer===oi ? "var(--success)" : "var(--border)" }} />
            </div>
          ))}
        </div>
      ))}

      <div style={{ display:"flex", gap:10, marginTop:8 }}>
        <button className="btn-sm" onClick={addQuestion} style={{ padding:"10px 20px" }}>+ Add Question</button>
        <button className="btn-add" onClick={save} style={{ flex:1, justifyContent:"center" }}>Save Quiz</button>
      </div>
    </div>
  );
}

// ── ADMIN USERS (FULL) ────────────────────────────────────────────────────────
function AdminUsers({ onToast, progress }) {
  const [users, setUsers]       = useState(JSON.parse(JSON.stringify(SEED_USERS)));
  const [editing, setEditing]   = useState(null);
  const [creating, setCreating] = useState(false);

  const blank = { id: Date.now(), username:"", password:"", name:"", role:"employee", avatar:"" };
  const employees = users.filter(u => u.role === "employee");

  function getProgress(uid) {
    const p = (progress && progress[uid]) || SEED_PROGRESS[uid] || {};
    return Math.round(Object.values(p).reduce((a,b)=>a+b,0) / (SEED_MODULES.length * 100) * 100);
  }

  function saveUser(u) {
    const avatar = u.name.split(" ").map(w=>w[0]).join("").toUpperCase().slice(0,2);
    const saved = { ...u, avatar };
    setUsers(prev => {
      const exists = prev.find(x => x.id === u.id);
      if (exists) return prev.map(x => x.id===u.id ? saved : x);
      return [...prev, saved];
    });
    setEditing(null);
    setCreating(false);
    onToast("✅ User saved!");
  }

  function deleteUser(id) {
    setUsers(prev => prev.filter(u => u.id !== id));
    onToast("🗑 User removed.");
  }

  if (editing || creating) {
    const u = creating ? blank : editing;
    return <UserForm user={u} onSave={saveUser} onCancel={() => { setEditing(null); setCreating(false); }} />;
  }

  return (
    <div>
      <div className="page-header">
        <h1>Manage Users</h1>
        <p>Add, edit, or remove employee accounts.</p>
      </div>
      <div style={{ display:"flex", justifyContent:"flex-end", marginBottom:16 }}>
        <button className="btn-add" onClick={() => setCreating(true)}>+ Add User</button>
      </div>
      <div className="table-wrap">
        <table className="team-table">
          <thead>
            <tr><th>Name</th><th>Username</th><th>Password</th><th>Progress</th><th>Role</th><th>Actions</th></tr>
          </thead>
          <tbody>
            {employees.map(u => (
              <tr key={u.id}>
                <td>
                  <div style={{ display:"flex", alignItems:"center", gap:10 }}>
                    <div className="avatar" style={{ width:30, height:30, fontSize:11 }}>{u.avatar}</div>
                    <span style={{ fontWeight:600 }}>{u.name}</span>
                  </div>
                </td>
                <td style={{ color:"var(--muted)" }}>{u.username}</td>
                <td style={{ color:"var(--muted)", fontFamily:"monospace", fontSize:12 }}>{u.password}</td>
                <td>
                  <div style={{ display:"flex", alignItems:"center", gap:8, minWidth:120 }}>
                    <div style={{ flex:1, height:6, background:"var(--surface2)", borderRadius:99, overflow:"hidden" }}>
                      <div style={{ height:"100%", width:`${getProgress(u.id)}%`, background:"linear-gradient(90deg,var(--gold),#f0c040)", borderRadius:99 }} />
                    </div>
                    <span style={{ fontSize:12, fontWeight:600, width:30 }}>{getProgress(u.id)}%</span>
                  </div>
                </td>
                <td><span className="pill pill-blue">{u.role}</span></td>
                <td>
                  <div style={{ display:"flex", gap:8 }}>
                    <button className="btn-sm" onClick={() => setEditing(u)}>Edit</button>
                    <button className="btn-sm" style={{ color:"var(--danger)" }} onClick={() => deleteUser(u.id)}>Remove</button>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

// ── USER FORM ─────────────────────────────────────────────────────────────────
function UserForm({ user, onSave, onCancel }) {
  const [form, setForm] = useState({ ...user });
  function set(k,v) { setForm(prev => ({ ...prev, [k]: v })); }
  const valid = form.name && form.username && form.password;

  return (
    <div>
      <div className="page-header">
        <h1>{user.name ? "Edit User" : "New User"}</h1>
      </div>
      <div style={{ background:"var(--surface)", border:"1px solid var(--border)", borderRadius:10, padding:28, maxWidth:480 }}>
        {[["Full Name","name"],["Username","username"],["Password","password"]].map(([label,key]) => (
          <div className="field-wrap" key={key}>
            <label className="field-label">{label}</label>
            <input className="field-input" value={form[key]||""} onChange={e=>set(key,e.target.value)}
              type={key==="password"?"password":"text"} placeholder={`Enter ${label.toLowerCase()}...`} />
          </div>
        ))}
        <div className="field-wrap">
          <label className="field-label">Role</label>
          <select className="field-input" value={form.role} onChange={e=>set("role",e.target.value)}>
            <option value="employee">Employee</option>
            <option value="admin">Admin</option>
          </select>
        </div>
        <div style={{ display:"flex", gap:10, marginTop:8 }}>
          <button className="btn-add" onClick={() => valid && onSave(form)} style={{ flex:1, justifyContent:"center",
            opacity: valid ? 1 : 0.5, cursor: valid ? "pointer" : "not-allowed" }}>Save User</button>
          <button className="btn-sm" onClick={onCancel} style={{ padding:"10px 20px" }}>Cancel</button>
        </div>
      </div>
    </div>
  );
}

// ── APP ROOT ─────────────────────────────────────────────────────────────────
export default function App() {
  const [user, setUser]         = useState(null);
  const [page, setPage]         = useState(null);
  const [toast, setToast]       = useState("");
  const [activeModule, setActiveModule] = useState(null);
  const [userProgress, setUserProgress] = useState(JSON.parse(JSON.stringify(SEED_PROGRESS)));

  function handleModuleComplete(moduleId, pct) {
    setUserProgress(prev => ({
      ...prev,
      [user.id]: { ...prev[user.id], [moduleId]: pct }
    }));
  }

  function showToast(msg) {
    setToast(msg);
    setTimeout(() => setToast(""), 3000);
  }

  function handleLogin(u) {
    setUser(u);
    setPage(u.role === "admin" ? "admin-dashboard" : "dashboard");
  }

  function handleLogout() {
    setUser(null);
    setPage(null);
  }

  function renderPage() {
    if (!user) return null;
    if (activeModule) return (
      <ModuleViewer
        user={user}
        moduleId={activeModule}
        onBack={() => setActiveModule(null)}
        onComplete={handleModuleComplete}
      />
    );
    switch (page) {
      case "dashboard":        return <EmployeeDashboard user={user} progress={userProgress} />;
      case "modules":          return <EmployeeModules user={user} onOpenModule={id => { setActiveModule(id); }} />;
      case "progress":         return <EmployeeProgress user={user} progress={userProgress} />;
      case "admin-dashboard":  return <AdminDashboard progress={userProgress} />;
      case "admin-team":       return <AdminTeamDetail progress={userProgress} />;
      case "admin-modules":    return <AdminModules onToast={showToast} />;
      case "admin-users":      return <AdminUsers onToast={showToast} progress={userProgress} />;
      default:                 return null;
    }
  }

  return (
    <>
      <style>{css}</style>
      {!user ? (
        <LoginScreen onLogin={handleLogin} />
      ) : (
        <div className="shell">
          <Sidebar user={user} page={page} setPage={setPage} onLogout={handleLogout} onClearModule={() => setActiveModule(null)} />
          <main className="main">{renderPage()}</main>
        </div>
      )}
      {toast && <div className="toast">{toast}</div>}
    </>
  );
}
